package com.colavite.gestor_investimento.repository;
import com.colavite.gestor_investimento.entity.*; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.test.context.ActiveProfiles; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.Instant; import static org.assertj.core.api.Assertions.assertThat;
@SpringBootTest @ActiveProfiles("test") @Transactional class OperacaoRepositoryTest { @Autowired OperacaoRepository operacoes; @Autowired CarteiraRepository carteiras; @Autowired AcaoRepository acoes;
 @Test void persisteOperacaoComForeignKeysEV4() { var c=carteiras.saveAndFlush(new Carteira("Teste","TESTE",null)); var a=acoes.saveAndFlush(new Acao("PETR4","Petrobras",Mercado.BRASIL,new BigDecimal("30"),Instant.now())); var o=operacoes.saveAndFlush(new Operacao(c,a,TipoOperacao.COMPRA,BigDecimal.TEN,new BigDecimal("30"),Instant.parse("2026-09-01T12:00:00Z"))); assertThat(operacoes.findById(o.getId())).isPresent(); assertThat(operacoes.findByCarteiraIdOrderByDataOperacaoAscIdAsc(c.getId())).hasSize(1); }
}
